window.DEX_DATA["sources:backport-7ff1e8148a3a4459"]={"json":{"skins":[{"filename":"knight.png"}],"names":[{"name":"波尔斯·德加尼斯爵士"},{"name":"哈姆雷特"},{"name":"拉里昂爵士"},{"name":"骑士蜗牛爵士"},{"name":"弗朗西斯"}],"chat":[{"lines":[{"text":"这些怪物怎么没完没了！"},{"text":"一波接着一波……还要牺牲多少生命，战斗才能结束？"}]},{"lines":[{"text":"比起成群的骷髅和僵尸，我更愿意和宝可梦对战！"}]},{"lines":[{"text":"为自己的信念而战，否则战斗毫无意义。"}]},{"lines":[{"text":"看似疯狂，其实也有章法。"}]}]}};
